n-items:center;gap:12px}.setting-top label{font-size:13px;font-weight:800;color:#4d5768}.value{color:#635bff;font-weight:800;font-size:14px}input[type=range]{width:100%;margin-top:12px;accent-color:#635bff}.actions{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:10px;margin-top:21px}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:45px;padding:11px 19px;border:0;border-radius:12px;cursor:pointer;font-size:13px;font-weight:800;transition:background .2s,transform .2s,opacity .2s}.btn-primary{background:#635bff;color:#fff}.btn-primary:hover{background:#5148e8;transform:translateY(-1px)}.btn-secondary{background:#eef0f5;color:#3f4858}.btn-secondary:hover{background:#e4e7ed}.btn:disabled{opacity:.6;cursor:not-allowed}.error{display:none;margin-top:15px;padding:12px 14px;border-radius:11px;background:#fff0f0;color:#c33;font-size:13px;text-align:center}.result{display:none;margin-top:25px;padding:18px;background:#fafbff;border:1px solid #e5e9f0;border-radius:17px}.result-preview{display:block;width:100%;max-width:520px;max-height:430px;object-fit:contain;margin:0 auto;background:#fff;border-radius:11px}.result-info{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.stat{padding:15px;background:#f6f7fb;border-radius:13px;text-align:center}.stat strong{display:block;color:#635bff;font-size:18px}.stat span{color:#707b8e;font-size:11px}.info-box{margin-top:24px;padding:25px;background:#fff;border:1px solid #e5e9f0;border-radius:19px}.info-box h2{margin-bottom:9px;font-size:21px}.info-box p,.info-box li{color:#707b8e;font-size:13px;line-height:1.7}.info-box ul{padding-left:20px;margin-top:10px}footer{padding:35px 20px;background:#151827;color:#fff;text-align:center}footer p{margin-top:6px;color:#aeb5c5;font-size:12px}@media(max-width:950px){.page-layout{width:calc(100% - 20px);gap:16px}}@media(max-width:700px){.navbar{min-height:64px}.nav-links{display:none;position:absolute;top:64px;left:0;right:0;padding:16px;flex-direction:column;background:#fff;border-bottom:1px solid #e5e9f0}.menu-button{display:block}.page-layout{width:calc(100% - 16px);margin-top:16px;flex-direction:column}.tool-content{width:100%;order:1}.page-layout>.tools-sidebar{width:100%;order:2}.desktop-ad{display:none}.mobile-ad{display:flex}.tool-header{padding:27px 17px}.maker-card{padding:16px}.upload-area{padding:38px 14px}.frames-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.result-info{grid-template-columns:1fr}.result-preview{max-height:300px}}
