<script>
const input=document.getElementById('fileInput'),area=document.getElementById('uploadArea'),grid=document.getElementById('framesGrid'),framesBox=document.getElementById('frames'),settings=document.getElementById('settings'),createBtn=document.getElementById('createBtn'),resetBtn=document.getElementById('resetBtn'),addMore=document.getElementById('addMore'),fileInfo=document.getElementById('fileInfo'),errorBox=document.getElementById('error'),result=document.getElementById('result'),preview=document.getElementById('resultPreview'),downloadBtn=document.getElementById('downloadBtn');let images=[],gifBlob=null;
function showError(m){errorBox.textContent=m;errorBox.style.display='block'}function clearError(){errorBox.textContent='';errorBox.style.display='none'}function render(){grid.innerHTML='';images.forEach((img,i)=>{const d=document.createElement('div');d.className='frame';d.innerHTML='<button class="remove-frame" type="button" data-i="'+i+'">×</button><img src="'+img.src+'" alt="Frame '+(i+1)+'"><span>Frame '+(i+1)+'</span>';grid.appendChild(d)});framesBox.style.display=images.length?'block':'none';settings.style.display=images.length>1?'block':'none';createBtn.disabled=images.length<2;fileInfo.textContent=images.length?images.length+' image'+(images.length>1?'s':'')+' selected':'No images selected'}
function addFiles(files){clearError();[...files].forEach(file=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)){return}const reader=new FileReader();reader.onload=e=>{const im=new Image();im.onload=()=>{images.push({src:e.target.result,img:im});render()};im.src=e.target.result};reader.readAsDataURL(file)});input.value=''}
area.onclick=()=>input.click();input.onchange=e=>addFiles(e.target.files);addMore.onclick=()=>input.click();['dragenter','dragover'].forEach(x=>area.addEventListener(x,e=>{e.preventDefault();area.classList.add('dragover')}));['dragleave','drop'].forEach(x=>area.addEventListener(x,e=>{e.preventDefault();area.classList.remove('dragover')}));area.addEventListener('drop',e=>addFiles(e.dataTransfer.files));grid.onclick=e=>{if(e.target.classList.contains('remove-frame')){images.splice(Number(e.target.dataset.i),1);render();result.style.display='none'}};document.getElementById('delay').oninput=e=>document.getElementById('delayValue').textContent=e.target.value+' ms';document.getElementById('width').oninput=e=>document.getElementById('widthValue').textContent=e.target.value==0?'Auto':e.target.value+' px';
function gifEncode(frames,w,h,delay){const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');let chunks=[];function frameBlob(i){if(i>=frames.length){const parts=chunks;const blob=new Blob(parts,{type:'image/gif'});gifBlob=blob;preview.src=URL.createObjectURL(blob);document.getElementById('frameCount').textContent=frames.length;document.getElementById('gifSize').textContent=(blob.size/1024).toFixed(1)+' KB';document.getElementById('gifTime').textContent=(frames.length*delay)+' ms';result.style.display='block';createBtn.disabled=false;return}ctx.clearRect(0,0,w,h);ctx.drawImage(frames[i],0,0,w,h);canvas.toBlob(b=>{if(!b){showError('GIF creation failed.');return}chunks.push(b);setTimeout(()=>frameBlob(i+1),20)},'image/gif');}frameBlob(0)}
createBtn.onclick=()=>{clearError();if(images.length<2){showError('Please select at least 2 images.');return}const delay=Number(document.getElementById('delay').value),width=Number(document.getElementById('width').value)||images[0].img.naturalWidth,ratio=images[0].img.naturalHeight/images[0].img.naturalWidth,height=Math.max(1,Math.round(width*ratio));/* Browser canvas cannot natively encode animated GIF frames. Use a lightweight animated-GIF encoder loaded only when needed. */if(!window.GIF){const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.js';s.onload=()=>buildGif(width,height,delay);s.onerror=()=>showError('GIF encoder could not be loaded. Please check your internet connection.');document.head.appendChild(s)}else buildGif(width,height,delay)};
function buildGif(width,height,delay){const worker='https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.worker.js';const gif=new GIF({workers:2,quality:10,width:width,height:height,workerScript:worker});images.forEach(x=>gif.addFrame(x.img,{delay:delay,copy:true}));createBtn.disabled=true;createBtn.textContent='Creating GIF...';gif.on('finished',blob=>{gifBlob=blob;preview.src=URL.createObjectURL(blob);document.getElementById('frameCount').textContent=images.length;document.getElementById('gifSize').textContent=(blob.size/1024).toFixed(1)+' KB';document.getElementById('gifTime').textContent=(images.length*delay)+' ms';result.style.display='block';createBtn.disabled=false;createBtn.textContent='Create GIF'});gif.render()}
downloadBtn.onclick=()=>{if(!gifBlob)return;const a=document.createElement('a');a.href=URL.createObjectURL(gifBlob);a.download='smarttoolz.gif';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};resetBtn.onclick=()=>{images=[];gifBlob=null;result.style.display='none';clearError();render()};render();
</script>
